def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of str, each token is an integer or one of '+', '-', '*', '/'.
    Return integer result with division truncating toward zero.
    """
    stack = []
    for token in tokens:
        if token not in {"+", "-", "*", "/"}:
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # Python // truncates toward negative infinity, need toward zero.
                # Use int(a / b) which truncates toward zero.
                stack.append(int(a / b))
    return stack[0]

